@push('scripts')<script>
const entryType=document.getElementById('entryType'),contractField=document.getElementById('contractField'),contractSelect=document.getElementById('contractSelect'),factoryRows=document.getElementById('factoryRows'),combinedTotal=document.getElementById('combinedTotal');
function renumber(){const rows=[...factoryRows.querySelectorAll('.factory-row')];rows.forEach((row,i)=>{row.querySelector('select').name=`factory_rows[${i}][factory_id]`;row.querySelector('.metres-input').name=`factory_rows[${i}][metres]`;row.querySelector('.remove-row').disabled=rows.length===1;});}
function updateTotal(){const sum=[...factoryRows.querySelectorAll('.metres-input')].reduce((total,input)=>total+(Number(input.value)||0),0);combinedTotal.textContent=sum.toFixed(2)+' m';}
function filterFactories(){const selected=contractSelect.selectedOptions[0],requiredFactory=selected&&selected.dataset.scope!=='all'?selected.dataset.factory:null;factoryRows.querySelectorAll('select').forEach(select=>{[...select.options].forEach(option=>{option.hidden=!!requiredFactory&&option.value!==''&&option.value!==requiredFactory;if(option.hidden&&option.selected)select.value='';});});}
function updateForm(){const stock=entryType.value==='own_stock';contractField.style.display=stock?'none':'flex';contractSelect.required=!stock;if(stock)contractSelect.value='';[...contractSelect.options].forEach(option=>{option.hidden=!!option.dataset.type&&option.dataset.type!==(entryType.value==='job_work'?'job_work':'fabric_rate');});if(contractSelect.selectedOptions[0]?.hidden)contractSelect.value='';filterFactories();}
document.getElementById('addFactory').addEventListener('click',()=>{const row=factoryRows.querySelector('.factory-row').cloneNode(true);row.querySelector('select').value='';row.querySelector('.metres-input').value='';factoryRows.append(row);renumber();filterFactories();});
factoryRows.addEventListener('click',event=>{if(event.target.classList.contains('remove-row')){event.target.closest('.factory-row').remove();renumber();updateTotal();}});
factoryRows.addEventListener('input',updateTotal);entryType.addEventListener('change',updateForm);contractSelect.addEventListener('change',filterFactories);updateForm();renumber();
</script>@endpush
@endsection
